import React from "react";

export function TotalBalanceOverview() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Balance Financiero</title>


    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

        body {
            font-family: 'Inter', sans-serif;
            background-color: #f8fafc;
        }

        .card {
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }

        .gradient-bg {
            background: linear-gradient(90deg, #3b82f6 0%, #8b5cf6 100%);
        }

        .time-selector {
            transition: all 0.2s ease;
        }

        .time-selector.active {
            background-color: #3b82f6;
            color: white;
        }
    </style>
</head>
<body class="min-h-screen flex items-center justify-center p-4">
    <div class="card bg-white rounded-2xl p-6 w-full max-w-md">

        <div class="flex justify-between items-start mb-6">
            <div>
                <p class="text-gray-500 text-sm font-medium">Total balance</p>
                <h1 class="text-3xl font-bold text-gray-800 mt-1">$11,920</h1>
            </div>
            <div class="bg-green-50 text-green-700 px-3 py-1.5 rounded-full text-sm font-semibold flex items-center">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 10l7-7m0 0l7 7m-7-7v18" />
                </svg>
                14.2%
            </div>
        </div>

        <!-- Gráfico -->
        <div class="relative mb-6">
            <canvas id="balanceChart" height="180"></canvas>
        </div>


        <div class="flex justify-between items-center mb-6">
            <p class="text-gray-500 text-sm">Jun 21</p>
            <p class="text-gray-800 font-semibold">$608.21</p>
        </div>

        <div class="flex justify-between bg-gray-100 p-1 rounded-lg">
            <button class="time-selector active py-2 px-4 rounded-md text-sm font-medium">1M</button>
            <button class="time-selector py-2 px-4 rounded-md text-sm font-medium">3M</button>
            <button class="time-selector py-2 px-4 rounded-md text-sm font-medium">6M</button>
            <button class="time-selector py-2 px-4 rounded-md text-sm font-medium">1Y</button>
            <button class="time-selector py-2 px-4 rounded-md text-sm font-medium">ALL</button>
        </div>
    </div>


</body>
</html>" }} />
